def transform(grid):
    import numpy as np
    from collections import Counter
    grid = np.array(grid)
    out = np.zeros_like(grid)
    # Check any 4x4 window (not just aligned) that has >= 10 pixels of same color
    # But here blocks are perfectly aligned at multiples of 4:
    for r in range(0, grid.shape[0], 4):
        for c in range(0, grid.shape[1], 4):
            sub = grid[r:r+4, c:c+4]
            counts = Counter(sub.flatten())
            # check if the block has > 50% of any color
            for col, cnt in counts.items():
                if col != 0 and cnt > 8:
                    out[r:r+4, c:c+4] = col
    return out.tolist()
